import json
from pathlib import Path
p=Path('src/course.json'); d=json.loads(p.read_text(encoding='utf-8'))

def make(i,title,typ,diff,statement,starter,solution,hint,explanation,tests,skills,runtime='stdout'):
    return {'id':i,'title':title,'type':typ,'difficulty':diff,'statement':statement,'starterCode':starter,'solution':solution,'hint':hint,'solutionExplanation':explanation,'tests':tests,'skillsChecked':skills,'runtime':runtime,'publicExamples':tests[:2],'hiddenTests':tests[2:]}

def t(inp,exp): return {'input':inp,'expected':exp}
