    (1,types,[{'title':'Типы значений','explanation':'Тип определяет, какие операции доступны значению.','example':'price = 1490\nactive = True','commonMistakes':['смешивание строки и числа','путаница None и "None"']},{'title':'Преобразование','explanation':'int, float и str явно меняют представление данных.','example':'count = int("3")','commonMistakes':['преобразование пустой строки','непроверенный ввод']}],['int','float','str','bool','None','type']),
