    d['topics'][topic]['lessons']=lessons; d['topics'][topic]['theory']=theory; d['topics'][topic]['terms']=terms; d['topics'][topic]['learningGoals']=['понимать тему на конкретных примерах','писать небольшие программы самостоятельно','проверять крайние случаи']; d['topics'][topic]['controlWork']={'title':f'Контрольная работа по теме {topic+1}','format':'10 конкретных задач с публичными и скрытыми тестами','passingScore':70,'skills':[x for l in lessons for x in l['skillsChecked'][:2]][:6]}
